update oa_sign_plan
plan_name = #{planName}, scenario = #{scenario}, post_name = #{postName}, employment_type = #{employmentType}, social_type = #{socialType}, service_person_type = #{servicePersonType}, insurance_type = #{insuranceType}, post_level_snapshot = #{postLevelSnapshot}, salary_version = #{salaryVersion}, entry_date = #{entryDate}, contract_start_date = #{contractStartDate}, contract_end_date = #{contractEndDate}, probation_start_date = #{probationStartDate}, probation_end_date = #{probationEndDate}, base_salary = #{baseSalary}, post_salary = #{postSalary}, field_allowance = #{fieldAllowance}, salary_total = #{salaryTotal}, shop_dept_id = #{shopDeptId}, legal_entity_id = #{legalEntityId}, legal_entity_name = #{legalEntityName}, rule_json = #{ruleJson}, default_values_json = #{defaultValuesJson}, sign_deadline_days = #{signDeadlineDays}, reminder_policy_json = #{reminderPolicyJson}, auto_send_condition_json = #{autoSendConditionJson}, status = #{status}, sort_order = #{sortOrder}, update_by = #{updateBy}, remark = #{remark}, update_time = sysdate()
where plan_id = #{planId}

mapper.select:
select 
from oa_sign_plan


        and plan_name like concat('%', #{planName}, '%')


        and (scenario = #{scenario}
             or (lower(#{scenario}) = 'renewal' and lower(trim(scenario)) = 'renew'))


        and post_name = #{postName}


        and employment_type = #{employmentType}


        and status = #{status}


    and shop_dept_id = 0

order by sort_order asc, plan_id desc
